def _default_weights_path() -> Path:
    app_root = Path(__file__).resolve().parents[2]
    return app_root / "checkpoints" / "denoising" / "best_generator.weights.h5"

def get_weights_path(weights_path: Optional[str] = None) -> Path:
    configured_path = weights_path or settings.DENOISING_WEIGHTS_PATH
    if not configured_path:
        return _default_weights_path()

    path = Path(configured_path).expanduser()
    if path.is_absolute():
        return path

    backend_root = Path(__file__).resolve().parents[3]
    return backend_root / path

def normalize(image: np.ndarray) -> np.ndarray:
    """Normalize pixel values to [0, 1]."""
    return image.astype(np.float32) / 255.0

def denormalize(image: np.ndarray) -> np.ndarray:
    """Convert back to uint8 [0, 255]."""
    return (image * 255).clip(0, 255).astype(np.uint8)

def load_grayscale_image(path: str) -> np.ndarray:
    """Load an image as a normalized grayscale float32 array."""
    image = Image.open(path).convert("L")
    return normalize(np.array(image, dtype=np.float32))

def _build_llm(provider: LLMProvider) -> ChatOpenAI:
    if provider == LLMProvider.openai:
        if not settings.OPENAI_API_KEY:
            raise RuntimeError("OPENAI_API_KEY not configured")
        return ChatOpenAI(
            model=settings.OPENAI_MODEL,
            api_key=settings.OPENAI_API_KEY,
            temperature=0.1,
        )

    # viewer / fallback → OpenRouter free model (NVIDIA Nemotron Nano)
    if not settings.OPENROUTER_API_KEY:
        raise RuntimeError("OPENROUTER_API_KEY not configured")
    return ChatOpenAI(
        model=settings.OPENROUTER_QWEN_MODEL,
        api_key=settings.OPENROUTER_API_KEY,
        base_url=settings.OPENROUTER_BASE_URL,
        temperature=0.1,
    )

def get_model_name(provider: LLMProvider) -> str:
    return (
        settings.OPENAI_MODEL
        if provider == LLMProvider.openai
        else settings.OPENROUTER_QWEN_MODEL
    )

def build_prompt() -> ChatPromptTemplate:
    return ChatPromptTemplate.from_messages(
        [
            ("system", SYSTEM_MESSAGE),
            ("human", HUMAN_MESSAGE),
        ]
    )

