def _configure_tesseract() -> None:
    """Honor TESSERACT_CMD from settings (Windows often needs an explicit path)."""
    cmd = (settings.TESSERACT_CMD or "").strip()
    # The user's .env may contain literal Python-raw-string quotes: r'C:\...'
    if cmd.startswith("r'") and cmd.endswith("'"):
        cmd = cmd[2:-1]
    elif cmd.startswith('r"') and cmd.endswith('"'):
        cmd = cmd[2:-1]
    elif (cmd.startswith("'") and cmd.endswith("'")) or (cmd.startswith('"') and cmd.endswith('"')):
        cmd = cmd[1:-1]
    if cmd:
        pytesseract.pytesseract.tesseract_cmd = cmd

def get_current_user(
    credentials: Annotated[HTTPAuthorizationCredentials | None, Depends(bearer_scheme)] = None,
    db: Session = Depends(get_db),
) -> User:
    if credentials is None or credentials.scheme.lower() != "bearer":
        raise AuthenticationError("Missing or invalid Authorization header")

    payload = decode_access_token(credentials.credentials)

    if payload.get("type") != "access":
        raise AuthenticationError("Not an access token")

    user_id = payload.get("sub")
    if not user_id:
        raise AuthenticationError("Invalid token subject")

    user = db.get(User, user_id)
    if user is None:
        raise AuthenticationError("User not found")
    if user.status.value == "banned":
        raise PermissionDenied("Account banned")

    return user

def require_roles(*roles: UserRole):
    """Dependency factory: ensures current user has one of the listed roles."""

    def _dep(current: User = Depends(get_current_user)) -> User:
        if current.role not in roles:
            raise PermissionDenied(
                f"Required role: {[r.value for r in roles]}, got {current.role.value}"
            )
        return current

    return _dep

"""Dependency factory: ensures current user has one of the listed roles."""

def _dep(current: User = Depends(get_current_user)) -> User:
    if current.role not in roles:
        raise PermissionDenied(
            f"Required role: {[r.value for r in roles]}, got {current.role.value}"
        )
    return current

return _dep

def get_llm_provider_for_user(user: User = Depends(get_current_user)) -> LLMProvider:
    """Backend picks LLM provider based on role — never trust client."""
    if user.role in (UserRole.user, UserRole.admin):
        return LLMProvider.openai
    return LLMProvider.openrouter_qwen

