function initials(name: string | null | undefined, email: string): string {
  const base = name?.trim() || email
  return base
    .split(/\s+|@/)
    .filter(Boolean)
    .slice(0, 2)
    .map((s) => s[0]?.toUpperCase() ?? '')
    .join('') || 'U'
}

